function lowestCap(nums: number[], k: number): number {
  const caps = [...new Set(nums)].sort((a, b) => a - b);
  for (const c of caps) {
    let count = 0;
    for (let i = 0; i < nums.length; i++) if (nums[i] <= c) { count++; i++; }
    if (count >= k) return c;
  }
  return caps[caps.length - 1];
}

