function lowestCap(nums: number[], k: number): number {
  const enough = (cap: number): boolean => {
    let count = 0;
    for (let i = 0; i < nums.length; i++) {
      if (nums[i] <= cap) { count++; i++; } // skip the neighbour
    }
    return count >= k;
  };
  let lo = Infinity, hi = -Infinity;
  for (const v of nums) { lo = Math.min(lo, v); hi = Math.max(hi, v); }
  while (lo < hi) {
    const mid = lo + Math.floor((hi - lo) / 2);
    if (enough(mid)) hi = mid;
    else lo = mid + 1;
  }
  return lo;
}

