            while i < n:
                if nums[i] <= cap:
                    count += 1
                    i += 2  # skip the neighbour
                else:
                    i += 1
            return count >= k

        lo, hi = min(nums), max(nums)
        while lo < hi:
            mid = (lo + hi) // 2
            if enough(mid):
                hi = mid
            else:
                lo = mid + 1
        return lo

